 return page(`${crumb(L('حسابي','My account'),'HGZ-2031')}<div class="section-head"><div><div class="kicker">Booking HGZ-2031</div><h1 class="title">Royal Garden · ${L('15 أكتوبر 2027','15 October 2027')}</h1><p class="section-copy">${L('صفحة واحدة للعقد، الدفعات، الـtimeline، بيانات القاعة والتغييرات.','One place for contract, payments, timeline, venue details, and changes.')}</p></div>${badge(L('مؤكد','Confirmed'),'green')}</div><div class="grid-3"><div class="card card-pad"><span class="tiny muted">${L('الإجمالي','Total')}</span><div class="metric-value">${money(145000)}</div></div><div class="card card-pad"><span class="tiny muted">${L('مدفوع','Paid')}</span><div class="metric-value text-green">${money(30000)}</div></div><div class="card card-pad"><span class="tiny muted">${L('المتبقي','Remaining')}</span><div class="metric-value">${money(115000)}</div></div></div><div class="grid-2 audit-gap"><div class="card card-pad"><h3>${L('رحلة الحجز','Booking timeline')}</h3><div class="timeline"><div class="timeline-item done"><span class="timeline-dot">✓</span><div><h4>${L('العربون مدفوع','Deposit paid')}</h4><p>${L('30,000 ج.م · الآن','30,000 EGP · now')}</p></div></div><div class="timeline-item done"><span class="timeline-dot">✓</span><div><h4>${L('القاعة أكدت','Venue confirmed')}</h4><p>${L('التاريخ اتقفل على VenueOS.','The date is blocked in VenueOS.')}</p></div></div><div class="timeline-item active"><span class="timeline-dot">3</span><div><h4>${L('تأكيد العدد النهائي','Final guest count')}</h4><p>${L('قبل المناسبة بـ14 يوم.','14 days before the event.')}</p></div></div><div class="timeline-item"><span class="timeline-dot">4</span><div><h4>${L('الدفع النهائي','Final payment')}</h4><p>${money(115000)}</p></div></div></div></div><div class="card card-pad"><h3>${L('إدارة الحجز','Manage booking')}</h3><div class="task-list"><button onclick="navTo('messages')"><span>✉</span><div><strong>${L('راسل القاعة','Message venue')}</strong><small>${L('كل الكلام مربوط بالحجز','Conversation stays attached to booking')}</small></div></button><button onclick="toast('${L('طلب تعديل العدد اتسجل كديمو','Guest-count change request added as demo')}')"><span>✎</span><div><strong>${L('طلب تعديل','Request change')}</strong><small>${L('عدد الضيوف أو الباقة','Guest count or package')}</small></div></button><button onclick="navTo('refund/HGZ-2031')"><span>↩</span><div><strong>${L('إلغاء / استرجاع','Cancel / refund')}</strong><small>${L('سياسة واضحة قبل التأكيد','Clear policy before confirmation')}</small></div></button></div><div class="contract-box"><strong>${L('العقد وسياسة الإلغاء','Contract & cancellation policy')}</strong><p>${L('Mock document preview للديمو: الشروط، مواعيد الدفعات، ونسب الاسترجاع حسب وقت الإلغاء.','Demo document preview: terms, payment milestones, and refund percentage by cancellation window.')}</p><button class="btn btn-light btn-sm" onclick="toast('${L('فتح عقد الديمو','Demo contract opened')}')">${L('عرض العقد','View contract')}</button></div></div></div>`);
